    "battleRoomMaxTeamSizeExceeded": "当前副本最多允许 {max} 人组队",
    "battleHelpTitle": "战斗帮助",
    "battleHelpSubtitle": "快速查看战斗流程、站位、结算与特殊模式规则。",
    "battleHelpFlowTitle": "房间与战斗流程",
    "battleHelpFlowLine1": "房间状态会在空闲、准备、进入副本、战斗中、重整中之间切换。",
    "battleHelpFlowLine2": "全员准备后进入副本倒计时，结束后自动开始战斗。",
    "battleHelpFlowLine3": "战斗失败进入重整阶段，重整结束后按房间配置决定是否自动重进。",
    "battleHelpFogTitle": "迷雾模式",
    "battleHelpFogLine1": "迷雾模式可在战斗房间配置中开启，用于进入当前副本的迷雾战斗。",
    "battleHelpFogLine2": "每次进入迷雾模式会消耗1张当前副本对应的迷雾地图。",
    "battleHelpFogLine3": "迷雾地图由5张对应副本的普通探索地图与1颗余辉凝炼而成。",
    "battleHelpFogLine4": "房主迷雾地图不足时，系统会自动关闭迷雾模式，当次以普通模式进入并弹出提示。",
    "battleHelpPositionTitle": "站位影响",
    "battleHelpPositionLine1": "通常情况下，前排的单位会优先成为攻击目标。",
    "battleHelpPositionLine2": "中排偏向均衡，常用于输出与过渡，或者躲避敌人针对最后排的远程攻击。",
    "battleHelpPositionLine3": "后排更适合远程输出与支援单位，后排的单位通常都可以存活到最后。",
    "battleHelpTurnTitle": "回合与冷却",
    "battleHelpTurnLine1": "单位按速度属性排序行动，速度越高越容易先手。",
    "battleHelpTurnLine2": "技能释放后先进入冷却，在自身回合结束时统一减少冷却回合。",
    "battleHelpTurnLine3": "冷却、生命和法力都会影响技能是否可释放。",
    "battleHelpDamageTitle": "伤害结算顺序",
    "battleHelpDamageLine1": "【伤害类型区分】物理伤害使用物理防御、物理增伤/减伤、暴击率/暴击伤害。",
    "battleHelpDamageLine2": "【伤害类型区分】魔法伤害使用魔法防御、魔法增伤/减伤、法术暴击率/法术暴击伤害。",
    "battleHelpDamageLine3": "【结算顺序】①基础伤害=技能/普攻公式；②防御减伤用K公式：有效防御=(防御-固定穿透)×(1-百分比穿透)；减伤%=防御/(100+防御)。",
    "battleHelpDamageLine4": "【结算顺序】③防御结算后判定暴击：暴击附加 暴击伤害×(1-暴击抵抗) 倍的额外伤害，暴击抵抗只对额外倍率部分生效。",
    "battleHelpDamageLine5": "【结算顺序】④最终乘算增伤与减伤（与防御独立的第二层乘算）：×(1+物理/魔法伤害增幅)×(1-物理/魔法伤害减免)，按伤害类型分别计算，不与防御叠加。",
    "battleHelpSkillTitle": "技能释放逻辑",
    "battleHelpSkillLine1": "单位会按技能序列依次尝试释放可用技能，不满足条件时自动跳过。",
    "battleHelpSkillLine2": "技能可配置目标范围、选目标规则、数量公式和多段效果。",
    "battleHelpSkillLine3": "效果支持伤害、治疗、施加状态，并可独立配置目标规则。",
    "battleHelpEnemyTitle": "敌人与掉落",
    "battleHelpEnemyLine1": "每个区域配置普通敌人池与特殊敌人池，特殊波次会额外出现特殊敌人。",
    "battleHelpEnemyLine2": "敌人支持在配置表中定义默认技能序列，会按顺序参与施法选择。",
    "battleHelpEnemyLine3": "敌人详情可查看属性、技能与掉落区间，便于战前规划。",
    "battleHelpRewardTitle": "结算与奖励",
    "battleHelpRewardLine1": "战斗胜利时，符合奖励资格的玩家会按玩家维度结算战斗经验与掉落。",
    "battleHelpRewardLine2": "敌人掉落、波次掉落与特殊掉落会按概率和数量区间独立结算，并受幸运、掉率加成与难度加成影响。",
    "battleHelpRewardLine3": "猫咪不会额外复制战利品掉落次数；猫咪增加敌人数量后，击败更多敌人会间接增加掉落机会。",
    "battleHelpKittyTitle": "猫咪助手参战",
    "battleHelpKittyLine1": "猫咪助手可以参战，并会像玩家单位一样计入额外敌人数量；召唤单位不计入该人数加成。",
    "battleHelpKittyLine2": "猫咪参战可获得战斗属性经验，使用技能可获得战斗技能经验；当前默认倍率为100%，不会扣减玩家经验。",
    "battleHelpKittyLine3": "猫咪助手的战斗属性等级受战斗等级上限限制，达到上限后将不会继续获得对应等级收益。",
    "battleHelpKittyLine4": "猫咪战斗等级上限可通过喂食特定道具提升，相关道具会标注提升的上限数值。",
    "battleHelpKittyLine5": "猫咪不参与战利品分配，也不会直接获得物品掉落。",
